// Zoom refresh tokens rotate: always persist the new refresh_token.
export async function refreshZoomToken(userId: string, db: TokenStore) {
  return db.withUserLock(userId, async () => {
    const current = await db.get(userId);
    if (current.expiresAt - Date.now() > 5 * 60_000) return current; // still fresh
    const basic = Buffer.from(`${process.env.ZOOM_CLIENT_ID}:${process.env.ZOOM_CLIENT_SECRET}`).toString("base64");
    const res = await fetch("https://zoom.us/oauth/token", {
      method: "POST",
      headers: { Authorization: `Basic ${basic}`, "Content-Type": "application/x-www-form-urlencoded" },
      body: new URLSearchParams({ grant_type: "refresh_token", refresh_token: current.refreshToken }),
    });
    if (!res.ok) {
      await db.markNeedsReconnect(userId, await res.text());
      throw new Error(`Zoom refresh failed: ${res.status}`);
    }
    const t = await res.json(); // { access_token, refresh_token, expires_in, scope, api_url }
    const next = { accessToken: t.access_token, refreshToken: t.refresh_token, expiresAt: Date.now() + t.expires_in * 1000, scope: t.scope, apiUrl: t.api_url };
    await db.save(userId, next); // same critical section as the refresh call
    return next;
  });
}
